(async () => {
  const root = document.querySelector('[data-window-gallery]');
  root.scrollIntoView();
  await new Promise(r => setTimeout(r, 6000));
  const g = window.__wgDebug;
  const size = g.renderer.getSize(new (Object.getPrototypeOf(g.camera.position).constructor)());
  const stage = root.querySelector('[data-wg-stage]');
  return {
    rendererSize: [Math.round(g.renderer.domElement.width), Math.round(g.renderer.domElement.height)],
    cssSize: [Math.round(stage.clientWidth), Math.round(stage.clientHeight)],
    canvasAttr: [g.renderer.domElement.width, g.renderer.domElement.height],
    distance: +g.camera.position.distanceTo(g.controls.target).toFixed(2),
    fov: g.camera.fov,
    pixelRatio: g.renderer.getPixelRatio()
  };
})()
